(* [comment removed for export] *)
Definition inv_dA (M : word -> option byte) (V S2 : Z) (g : eghost) (d : Z) : Prop :=
  PMESA.enc_objA L IC EC M V S2 d /\ PMESA.stack_at L M V (g_es g) (g_sb g) (g_scap g) /\ PMESA.stack_sh M (g_es g) (g_sb g) (g_scap g) /\
  PMESA.sink_atA L M S2 (g_rep g) /\ len (PML.srep_chars (g_rep g)) = g_len g /\ depth (g_es g) <= MAX_DEPTH /\ PMESA.lbv_rng V S2 g.

(* [comment removed for export] *)
Definition objI (M : word -> option byte) (V S2 dI dD : Z) : Prop :=
  PMSA.u64 L M V (PMLA.VT_VISITOR IC) /\ PMSA.u64 L M (V + O_SINK) S2 /\ PMSA.u64 L M (V + O_OPT_VPTR) (PMESA.VT_ENC_OPTIONS EC) /\
  (exists fl, PMSA.u8 L M (V + O_FLAGS) fl /\ Z.land fl 15 = 0) /\
  PMSA.u8 L M (V + O_BIGNUM_FMT) 0 /\
  PMSA.u8 L M (V + O_SPLITS) 0 /\ PMSA.u8 L M (V + O_SPLITS + 1) 0 /\ PMSA.u8 L M (V + O_SPLITS + 2) 0 /\ PMSA.u8 L M (V + O_SPLITS + 3) 0 /\ PMSA.u8 L M (V + O_SPLITS + 4) 0 /\
  PMSA.u8 L M (V + O_INDENT_SIZE) 4 /\ PMSA.u64 L M (V + O_LINE_LIMIT) 120 /\
  PMSA.u64 L M (V + O_NL_CHARS) 0xa02 /\ PMSA.u64 L M (V + O_NL_CHARS + 8) 0 /\ PMSA.u64 L M (V + O_NL_CHARS + 16) 0 /\ L5.defined M (V + O_NL_CHARS) 24 /\
  PMSA.u64 L M (V + O_COMMON_VPTR) (PMESA.VT_ENC_COMMON EC) /\ (exists en, PMSA.u8 L M (V + O_ENABLE) en /\ Z.land en 63 = 0 /\ L5.defined M (V + O_ENABLE) 2) /\
  PMSA.u32 L M (V + O_MAX_DEPTH) MAX_DEPTH /\ PMSA.u8 L M (V + O_INDENT_CHAR) 32 /\
  PMSA.u8 L M (V + O_FP) 0 /\ PMSA.u32 L M (V + O_FP + 4) 0 /\ (exists dp, PMSA.u8 L M (V + O_FP + 8) dp) /\
  PMSA.u32 L M (V + O_INDENT) (4 * dI) /\ L5.defined M (V + O_COLUMN) 8 /\ PMSA.u32 L M (V + O_DEPTH) dD /\
  PMESA.sv_at L M (V + O_COLON) (PMESA.TXT_COLON EC) 2 /\ PMESA.sv_at L M (V + O_COMMA) (PMESA.TXT_COMMA EC) 2 /\ PMESA.sv_at L M (V + O_OBRACE) (PMESA.TXT_OBRACE EC) 1 /\ PMESA.sv_at L M (V + O_CBRACE) (PMESA.TXT_CBRACE EC) 1 /\
  PMESA.sv_at L M (V + O_OBRACKET) (PMESA.TXT_OBRACKET EC) 1 /\ PMESA.sv_at L M (V + O_CBRACKET) (PMESA.TXT_CBRACKET EC) 1 /\
  L5.defined M V ENC_SIZE.
